def find_intermediate_string(s, t):
    n = len(s)
    result = list(s)

    for i in range(n - 1, -1, -1):
        if s[i] != 'z':
            result[i] = chr(ord(s[i]) + 1)
            for j in range(i + 1, n):
                result[j] = 'a'
            break
    else:
